CREATE TABLE IF NOT EXISTS nestdutio_form_records(id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64) NOT NULL,version_id VARCHAR(64) NOT NULL,form_id VARCHAR(40) NOT NULL,request_key VARCHAR(100) NOT NULL,body_hash VARCHAR(64) NOT NULL,schema_json LONGTEXT NOT NULL,values_json TEXT NOT NULL,created_at VARCHAR(32) NOT NULL,UNIQUE KEY nestdutio_form_request(project_id,form_id,request_key),KEY nestdutio_records_project(project_id,created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
